mapper.sql:
WHERE p.delete_yn = 'N'

  AND p.site_id = #{search.siteId}


  AND p.popup_type = #{search.popupType}


  AND p.use_yn = #{search.useYn}


  AND p.popup_title LIKE CONCAT('%', #{search.keyword}, '%')

mapper.select:

SELECT



  FROM tb_popup p
  LEFT JOIN tb_site s ON s.site_id = p.site_id
 WHERE p.delete_yn  = 'N'
   AND p.use_yn     = 'Y'
   AND p.site_id    = #{siteId}
   AND p.show_from <= #{now}
   AND p.show_to   >= #{now}
 ORDER BY p.sort_order ASC, p.created_at DESC

SELECT MAX(sort_order)
  FROM tb_popup
 WHERE site_id = #{siteId}

mapper.delete:
DELETE FROM tb_popup
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
